<script setup>
import { reactive, ref } from 'vue'
import FloatingWindow from '../components/common/FloatingWindow.vue'
import NeonPanel from '../components/common/NeonPanel.vue'
import { useAppStore } from '../stores/app'
const store=useAppStore();const identityWindow=ref(false);const runtimeWindow=ref(false);const vcenterWindow=ref(false);const importSummary=ref('')
const branding=reactive({productName:store.catalog.settings.branding?.productName||'POSHinit Control Plane',supportEmail:store.catalog.settings.branding?.supportEmail||'ops@example.com'});const runtime=reactive({defaultShell:store.catalog.settings.runtime?.defaultShell||'pwsh',allowManualRuns:store.catalog.settings.runtime?.allowManualRuns??true});const vcenter=reactive({baseUrl:store.catalog.settings.vcenter?.baseUrl||'',username:store.catalog.settings.vcenter?.username||'',passwordPlain:'',verifyTls:store.catalog.settings.vcenter?.verifyTls||false,autoImportGroupId:store.catalog.settings.vcenter?.autoImportGroupId||''})
async function saveIdentity(){await store.saveSettings('branding',branding);identityWindow.value=false}async function saveRuntime(){await store.saveSettings('runtime',runtime);runtimeWindow.value=false}async function saveVcenter(){await store.saveSettings('vcenter',vcenter)}async function importMachines(){const imported=await store.importVcenter(vcenter);importSummary.value=`Imported ${imported.length} virtual machine records.`}
</script>
<template><div class="settings-workspace"><div class="toolbar-row commandbar"><div><p class="section-eyebrow">Control Plane Configuration</p><h2 class="page-title">System Settings</h2></div><v-chip variant="outlined">configuration secured</v-chip></div><div class="settings-grid"><NeonPanel subtitle="Portal" title="Identity"><template #actions><v-btn size="small" variant="text" @click="identityWindow=true">Configure</v-btn></template><div class="setting-card"><v-icon icon="mdi-badge-account-outline"/><strong>{{branding.productName}}</strong><span>{{branding.supportEmail}}</span></div></NeonPanel><NeonPanel subtitle="Execution" title="Runtime"><template #actions><v-btn size="small" variant="text" @click="runtimeWindow=true">Configure</v-btn></template><div class="setting-card"><v-icon icon="mdi-console-line"/><strong>{{runtime.defaultShell}}</strong><span>Manual runs {{runtime.allowManualRuns?'enabled':'disabled'}}</span></div></NeonPanel><NeonPanel subtitle="Infrastructure" title="vCenter Sync"><template #actions><v-btn size="small" variant="text" @click="vcenterWindow=true">Configure</v-btn></template><div class="setting-card"><v-icon icon="mdi-cloud-sync-outline"/><strong>{{vcenter.baseUrl||'Not configured'}}</strong><span>VMware inventory connector</span></div></NeonPanel></div><NeonPanel subtitle="Security Posture" title="Runtime Protections"><div class="protection-list"><article><v-icon icon="mdi-shield-check-outline" color="success"/>Helmet headers and configurable CORS protect the Express host.</article><article><v-icon icon="mdi-database-lock-outline" color="info"/>SQLite queries use parameterized access paths.</article><article><v-icon icon="mdi-key-chain-variant" color="secondary"/>Vault payloads are sealed through AES-256-GCM.</article></div></NeonPanel><FloatingWindow v-model="identityWindow" title="Portal Identity" :width="460" :start-x="190" :start-y="115"><div class="window-form"><v-text-field v-model="branding.productName" label="Product name"/><v-text-field v-model="branding.supportEmail" label="Support email"/><div class="actions"><v-btn variant="text" @click="identityWindow=false">Cancel</v-btn><v-btn class="glass-button" @click="saveIdentity">Save Identity</v-btn></div></div></FloatingWindow><FloatingWindow v-model="runtimeWindow" title="Execution Runtime" :width="460" :start-x="430" :start-y="145"><div class="window-form"><v-text-field v-model="runtime.defaultShell" label="PowerShell executable"/><v-switch v-model="runtime.allowManualRuns" color="secondary" label="Allow manual dispatch"/><div class="actions"><v-btn variant="text" @click="runtimeWindow=false">Cancel</v-btn><v-btn class="glass-button" @click="saveRuntime">Save Runtime</v-btn></div></div></FloatingWindow><FloatingWindow v-model="vcenterWindow" title="vCenter Inventory Connector" :width="560" :start-x="250" :start-y="85"><div class="window-form"><v-text-field v-model="vcenter.baseUrl" label="vCenter base URL"/><div class="two"><v-text-field v-model="vcenter.username" label="Username"/><v-text-field v-model="vcenter.passwordPlain" label="Password" type="password"/></div><v-select v-model="vcenter.autoImportGroupId" :items="store.catalog.groups" item-title="name" item-value="id" label="Auto-assign deployment group"/><v-switch v-model="vcenter.verifyTls" color="secondary" label="Verify TLS certificates"/><v-alert v-if="importSummary" type="info" variant="tonal">{{importSummary}}</v-alert><div class="actions"><v-btn variant="text" @click="vcenterWindow=false">Close</v-btn><v-btn variant="text" prepend-icon="mdi-cloud-download-outline" @click="importMachines">Import VMs</v-btn><v-btn class="glass-button" @click="saveVcenter">Save Connector</v-btn></div></div></FloatingWindow></div></template>
<style scoped>.settings-workspace{display:grid;gap:14px}.commandbar{padding:2px 0 4px}.settings-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.setting-card{display:grid;gap:7px;padding:15px}.setting-card .v-icon{color:var(--amber)}.setting-card strong{overflow:hidden;font-family:'Share Tech Mono',monospace;font-size:.8rem;text-overflow:ellipsis;white-space:nowrap}.setting-card span{color:var(--muted);font-size:.72rem}.protection-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;padding:14px}.protection-list article{display:flex;gap:10px;padding:12px;border:1px solid var(--line);background:rgba(190,77,255,.05);font-size:.78rem}.window-form{display:grid;gap:12px}.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.actions{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap}@media(max-width:850px){.settings-grid,.protection-list{grid-template-columns:1fr}.two{grid-template-columns:1fr}}</style>
